-- Club Property Access Management schema.
-- Conventions: no foreign keys (service layer owns integrity); records are deactivated, not deleted.

CREATE TABLE IF NOT EXISTS properties (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  name VARCHAR(255) NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_properties_tenant (tenant_id, active)
);

CREATE TABLE IF NOT EXISTS gates (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  property_id INT UNSIGNED NOT NULL,
  name VARCHAR(255) NOT NULL,
  latitude DECIMAL(9,6) NULL,
  longitude DECIMAL(9,6) NULL,
  code VARCHAR(64) NULL,            -- combination lock code; never cached or logged
  access_token VARCHAR(128) NULL,   -- long random token in the gate's QR link; regenerated by admins only
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY idx_gates_property (tenant_id, property_id, active),
  UNIQUE KEY uq_gates_access_token (access_token)
);
-- Existing databases: ALTER TABLE gates ADD COLUMN access_token VARCHAR(128) NULL AFTER code,
--   ADD UNIQUE KEY uq_gates_access_token (access_token);  (tokens are then created on first use)

-- Audit of every gate code change. Records who/when/gate, never the code values themselves.
CREATE TABLE IF NOT EXISTS gate_code_audit (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  gate_id INT UNSIGNED NOT NULL,
  property_id INT UNSIGNED NOT NULL,
  gate_name VARCHAR(255) NOT NULL,
  action VARCHAR(16) NOT NULL,       -- 'create' | 'update' | 'clear'
  changed_by_user_id INT NOT NULL,
  changed_by_name VARCHAR(255) NOT NULL,
  changed_by_role VARCHAR(64) NOT NULL,
  changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_audit_gate (tenant_id, gate_id, changed_at),
  KEY idx_audit_time (tenant_id, changed_at)
);

-- One row per user, gate and day: the in and out scans of that visit share the record (for reporting).
-- status is the latest scan; in_at keeps the first 'in' of the day, out_at the latest 'out'.
CREATE TABLE IF NOT EXISTS property_access (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  user_id INT NOT NULL,
  user_name VARCHAR(255) NOT NULL,
  property_id INT UNSIGNED NOT NULL,
  gate_id INT UNSIGNED NOT NULL,
  access_date DATE NOT NULL,
  status VARCHAR(3) NOT NULL,        -- 'in' | 'out'
  in_at DATETIME NULL,
  out_at DATETIME NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_access_visit (tenant_id, user_id, gate_id, access_date),
  KEY idx_access_property (tenant_id, property_id, access_date),
  KEY idx_access_status (tenant_id, status, access_date)
);

-- Club members. Matched to auth users by email: user_id/first_name/last_name are filled in when validate-api is called.
CREATE TABLE IF NOT EXISTS members (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  member_number VARCHAR(32) NOT NULL,
  email VARCHAR(255) NOT NULL,
  phone VARCHAR(32) NOT NULL,
  first_name VARCHAR(100) NULL,
  last_name VARCHAR(100) NULL,
  user_id INT NULL,                  -- auth user id, set on first validated request with a matching email
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_members_number (tenant_id, member_number),
  KEY idx_members_email (tenant_id, email),
  KEY idx_members_user (tenant_id, user_id)
);

-- Which members control which gates. A Gate Controller only sees and edits the gates linked here.
CREATE TABLE IF NOT EXISTS gate_controllers (
  id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  tenant_id VARCHAR(64) NOT NULL,
  gate_id INT UNSIGNED NOT NULL,
  member_id INT UNSIGNED NOT NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_gate_controller (tenant_id, gate_id, member_id),
  KEY idx_gc_member (tenant_id, member_id, active)
);
